def intersection_nested_lists(l1, l2):
    """Write a function to find the nested list elements which are present in another list."""
    try:
        present = set(l1)
        return [[element for element in sublist if element in present] for sublist in l2]
    except TypeError:
        # Fall back to equality-based lookup for unhashable elements.
        return [[element for element in sublist if element in l1] for sublist in l2]
